"use client";

import { createClient, type SupabaseClient } from "@supabase/supabase-js";

/**
 * Browser anon client for Auth email links (invite + password reset).
 * Those emails are generated by the server and arrive as `#access_token=…` links, which only the
 * implicit flow understands (the PKCE flow rejects them as "not a valid PKCE flow url").
 * Not for catalogue reads — use the shared anon helper server-side instead.
 */
export function createBrowserAuthClient(): SupabaseClient | null {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL?.trim();
  const key = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY?.trim();
  if (!url || !key) return null;

  return createClient(url, key, {
    auth: {
      persistSession: true,
      autoRefreshToken: true,
      detectSessionInUrl: true,
      flowType: "implicit",
    },
  });
}
